import java.text.Normalizer;
import java.util.List;
import java.util.Locale;
import java.util.Set;
import java.util.regex.Pattern;

/**
 * The criteria used by both customer page and count queries.
 *
 * @param name     free-form name search text
 * @param statuses statuses to include; an empty set includes every status
 */
public record CustomerFilter(String name, Set<CustomerStatus> statuses) {

    private static final Pattern MARKS = Pattern.compile("\\p{M}+");

    public CustomerFilter {
        name = name == null ? "" : name;
        statuses = statuses == null ? Set.of() : Set.copyOf(statuses);
    }

    public static CustomerFilter empty() {
        return new CustomerFilter("", Set.of());
    }

    /** Whether these criteria match the unfiltered data set. */
    public boolean isEmpty() {
        return nameTerms().isEmpty() && statuses.isEmpty();
    }

    /** Normalized, non-empty name terms. */
    public List<String> nameTerms() {
        String normalized = normalize(name).trim();
        return normalized.isEmpty() ? List.of() : List.of(normalized.split("\\s+"));
    }

    /** Case- and accent-insensitive text used by repository matching. */
    public static String normalize(String value) {
        String decomposed = Normalizer.normalize(value, Normalizer.Form.NFD);
        return MARKS.matcher(decomposed).replaceAll("").toLowerCase(Locale.ROOT);
    }
}
